/// Emits the given frame verbatim onto the stream. Every converter in both directions runs on
/// every field of every output type, which is the round-trip test of the generated C++.
struct EchoTestFrameCommand {
    static constexpr std::string_view type_tag = "echoTestFrame";

    ::session_bridge::Frame frame;

    explicit EchoTestFrameCommand(::session_bridge::Frame frame_) :
            frame{std::move(frame_)} {}
};

/// Everything the app asks libsession to do. One Request goes in, exactly one Response comes
/// back carrying the same id. Commands are named for what the app wants, not for the C++ method
/// that serves them, so that a refactor upstream is a shim change rather than a protocol change.
using Command = std::variant<
        GetAccountInfoCommand,
        CreateAccountCommand,
        RestoreAccountFromWordsCommand,
        CheckRecoveryPhraseCommand,
        RestoreAccountFromSeedCommand,
        DiscardAccountCommand,
        KeepAccountCommand,
        GetSeedMnemonicCommand,
        SetDisplayNameCommand,
        AttachNetworkCommand,
        SetPollIntervalCommand,
        PollOnceCommand,
        SetPushTokenCommand,
        HandlePushPayloadCommand,
        GetConversationsCommand,
        GetMessageRequestsCommand,
        GetConversationCommand,
        OpenDmCommand,
        MarkReadCommand,
        SetBlockedCommand,
        SetNicknameCommand,
        SetPriorityCommand,
        ApproveConversationCommand,
        DeleteConversationCommand,
        GetMessagesCommand,
        SendMessageCommand,
        RetrySendCommand,
        DeleteMessageCommand,
        GetPrefCommand,
        SetPrefCommand,
        DeliverTestMessageCommand,
        GetTestAccountSeedCommand,
        ApproveTestContactCommand,
        EchoTestFrameCommand>;

struct Request {
    double id;
    ::session_bridge::Command command;

    Request(double id_, ::session_bridge::Command command_) :
            id{std::move(id_)}, command{std::move(command_)} {}
};

